// @pit: {"label": "Simplify banner patterns into two named constants"}
async ({ workspace: { search, edit, read } }, p: { content: string }) => {
  const sr = await search("npm announces the script", { path: "src/renderers/npm-result.ts", contextLines: 10 });
  const m = sr.matches[0];
  const endLine = m.after.find(a => a.text === "});")!;
  await edit("src/renderers/npm-result.ts", { revision: m.revision, changes: [{ kind: "replace", start: m.anchor, end: endLine.anchor, content: p.content }] });
  return (await read("src/renderers/npm-result.ts", { format: "raw", offset: m.line - 2, limit: 16 })).content;
}

